    const result = await runInvocation({
      agent,
      specDir: testDir,
      sessionsDir: path.join(testDir, "sessions"),
      cwd: process.cwd(),
      taskRef: "@" + testUlid("TASK"),
      prompt: "Shadow commit on timeout",
